{
  "name": "GPIB通信适配器",
  "name_en": "GPIB Communication Adapter",
  "manufacturer": "",
  "description": "这是一种将计算机与采用 IEEE-488/GPIB 接口的实验仪器连接起来的通信适配器，常见形式为 GPIB-USB 或 GPIB-以太网桥接器。它用于实验室中对万用表、源表、示波器、频谱仪等台式仪器进行远程控制、命令发送和数据采集。",
  "description_en": "This is a communication adapter that links a computer to laboratory instruments using the IEEE-488/GPIB interface, commonly as a GPIB-to-USB or GPIB-to-Ethernet bridge. It is used in labs for remote control, command transmission, and data acquisition from bench instruments such as multimeters, source meters, oscilloscopes, and spectrum analyzers.",
  "tag_hints": [
    "GPIB",
    "IEEE-488",
    "instrument control",
    "USB-to-GPIB",
    "Ethernet-to-GPIB",
    "lab automation",
    "remote communication"
  ],
  "actions": [
    {
      "action_name": "auto-address",
      "description": "获取或设置 GPIB 地址和下游地址。",
      "description_en": "Get or set the GPIB address and downstream address."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与 GPIB 适配器的连接。",
      "description_en": "Close the connection to the GPIB adapter."
    },
    {
      "action_name": "auto-eoi",
      "description": "获取或设置 EOI 使用状态。",
      "description_en": "Get or set the EOI usage status."
    },
    {
      "action_name": "auto-eos",
      "description": "获取或设置结束字符串（EOS）字符。",
      "description_en": "Get or set the end-of-string (EOS) character."
    },
    {
      "action_name": "auto-flush_input",
      "description": "清空输入缓冲区。",
      "description_en": "Flush the input buffer."
    },
    {
      "action_name": "auto-read",
      "description": "从已连接的 GPIB 仪器读取文本数据。",
      "description_en": "Read text data from the connected GPIB instrument."
    },
    {
      "action_name": "auto-read_raw",
      "description": "从已连接的 GPIB 仪器读取原始字节数据。",
      "description_en": "Read raw byte data from the connected GPIB instrument."
    },
    {
      "action_name": "auto-terminator",
      "description": "获取或设置通信终止符。",
      "description_en": "Get or set the communication terminator."
    },
    {
      "action_name": "auto-timeout",
      "description": "获取或设置通信超时时间。",
      "description_en": "Get or set the communication timeout."
    },
    {
      "action_name": "auto-write",
      "description": "向已连接的 GPIB 仪器写入文本命令或数据。",
      "description_en": "Write text commands or data to the connected GPIB instrument."
    },
    {
      "action_name": "auto-write_raw",
      "description": "向已连接的 GPIB 仪器写入原始字节数据。",
      "description_en": "Write raw byte data to the connected GPIB instrument."
    }
  ]
}

